50	function mirrorPos(pos: string): string {
51	    pos = pos === 'left'
52	        ? 'right'
53	        : pos === 'right'
54	        ? 'left'
55	        : pos === 'top'
56	        ? 'bottom'
57	        : 'top';
58	    return pos;
59	}
