120	function assembleTransform(x: number, y: number, toString?: boolean) {
121	    // If using float on style, the final width of the dom might
122	    // keep changing slightly while mouse move. So `toFixed(0)` them.
123	    const x0 = x.toFixed(0) + 'px';
124	    const y0 = y.toFixed(0) + 'px';
125	    // not support transform, use `left` and `top` instead.
126	    if (!env.transformSupported) {
127	        return toString
128	            ? `top:${y0};left:${x0};`
129	            : [['top', y0], ['left', x0]];
130	    }
131	    // support transform
132	    const is3d = env.transform3dSupported;
133	    const translate = `translate${is3d ? '3d' : ''}(${x0},${y0}${is3d ? ',0' : ''})`;
134	    return toString
135	        ? 'top:0;left:0;' + CSS_TRANSFORM_VENDOR + ':' + translate + ';'
136	        : [['top', 0], ['left', 0], [TRANSFORM_VENDOR, translate]];
137	}
