139	/**
140	 * @param {Object} textStyle
141	 * @return {string}
142	 * @inner
143	 */
144	function assembleFont(textStyleModel: Model<TooltipOption['textStyle']>): string {
145	    const cssText = [];
146	
147	    const fontSize = textStyleModel.get('fontSize');
148	    const color = textStyleModel.getTextColor();
149	
150	    color && cssText.push('color:' + color);
151	
152	    cssText.push('font:' + textStyleModel.getFont());
153	
154	    fontSize
155	        // @ts-ignore, leave it to the tooltip refactor.
156	        && cssText.push('line-height:' + Math.round(fontSize * 3 / 2) + 'px');
157	
158	    const shadowColor = textStyleModel.get('textShadowColor');
159	    const shadowBlur = textStyleModel.get('textShadowBlur') || 0;
160	    const shadowOffsetX = textStyleModel.get('textShadowOffsetX') || 0;
161	    const shadowOffsetY = textStyleModel.get('textShadowOffsetY') || 0;
162	    shadowColor && shadowBlur
163	        && cssText.push('text-shadow:' + shadowOffsetX + 'px ' + shadowOffsetY + 'px '
164	            + shadowBlur + 'px ' + shadowColor);
165	
166	    each(['decoration', 'align'] as const, function (name) {
167	        const val = textStyleModel.get(name);
168	        val && cssText.push('text-' + name + ':' + val);
169	    });
170	
171	    return cssText.join(';');
172	}
