174	function assembleCssText(tooltipModel: Model<TooltipOption>, enableTransition?: boolean, onlyFade?: boolean) {
175	    const cssText: string[] = [];
176	    const transitionDuration = tooltipModel.get('transitionDuration');
177	    const backgroundColor = tooltipModel.get('backgroundColor');
178	    const shadowBlur = tooltipModel.get('shadowBlur');
179	    const shadowColor = tooltipModel.get('shadowColor');
180	    const shadowOffsetX = tooltipModel.get('shadowOffsetX');
181	    const shadowOffsetY = tooltipModel.get('shadowOffsetY');
182	    const textStyleModel = tooltipModel.getModel('textStyle');
183	    const padding = getPaddingFromTooltipModel(tooltipModel, 'html');
184	    const boxShadow = `${shadowOffsetX}px ${shadowOffsetY}px ${shadowBlur}px ${shadowColor}`;
185	
186	    cssText.push('box-shadow:' + boxShadow);
187	    // Animation transition. Do not animate when transitionDuration is 0.
188	    enableTransition && transitionDuration && cssText.push(assembleTransition(transitionDuration, onlyFade));
189	
190	    if (backgroundColor) {
191	        cssText.push('background-color:' + backgroundColor);
192	    }
193	
194	    // Border style
195	    each(['width', 'color', 'radius'] as const, function (name) {
196	        const borderName = 'border-' + name;
197	        const camelCase = toCamelCase(borderName) as 'borderWidth' | 'borderColor' | 'borderRadius';
198	        const val = tooltipModel.get(camelCase);
199	        val != null
200	            && cssText.push(borderName + ':' + val + (name === 'color' ? '' : 'px'));
201	    });
202	
203	    // Text style
204	    cssText.push(assembleFont(textStyleModel));
205	
206	    // Padding
207	    if (padding != null) {
208	        cssText.push('padding:' + normalizeCssArray(padding).join('px ') + 'px');
209	    }
210	
211	    return cssText.join(';') + ';';
212	}
