214	// If not able to make, do not modify the input `out`.
215	function makeStyleCoord(
216	    out: number[],
217	    zr: ZRenderType,
218	    container: HTMLElement | null | undefined,
219	    zrX: number,
220	    zrY: number
221	) {
222	    const zrPainter = zr && zr.painter;
223	
224	    if (container) {
225	        const zrViewportRoot = zrPainter && zrPainter.getViewportRoot();
226	        if (zrViewportRoot) {
227	            // Some APPs might use scale on body, so we support CSS transform here.
228	            transformLocalCoord(out, zrViewportRoot, container, zrX, zrY);
229	        }
230	    }
231	    else {
232	        out[0] = zrX;
233	        out[1] = zrY;
234	        // xy should be based on canvas root. But tooltipContent is
235	        // the sibling of canvas root. So padding of ec container
236	        // should be considered here.
237	        const viewportRootOffset = zrPainter && (zrPainter as CanvasPainter | SVGPainter).getViewportRootOffset();
238	        if (viewportRootOffset) {
239	            out[0] += viewportRootOffset.offsetLeft;
240	            out[1] += viewportRootOffset.offsetTop;
241	        }
242	    }
243	
244	    out[2] = out[0] / zr.getWidth();
245	    out[3] = out[1] / zr.getHeight();
246	}
