285	    constructor(
286	        api: ExtensionAPI,
287	        opt: TooltipContentOption
288	    ) {
289	        if (env.wxa) {
290	            return null;
291	        }
292	
293	        const el = document.createElement('div');
294	        // TODO: TYPE
295	        (el as any).domBelongToZr = true;
296	        this.el = el;
297	        const zr = this._zr = api.getZr();
298	
299	        const appendTo = opt.appendTo;
300	        const container: HTMLElement | null | undefined = appendTo && (
301	            isString(appendTo)
302	                ? document.querySelector(appendTo)
303	                : isDom(appendTo)
304	                    ? appendTo
305	                    : isFunction(appendTo) && appendTo(api.getDom())
306	        );
307	
308	        makeStyleCoord(this._styleCoord, zr, container, api.getWidth() / 2, api.getHeight() / 2);
309	
310	        (container || api.getDom()).appendChild(el);
311	
312	        this._api = api;
313	        this._container = container;
314	
315	        // FIXME
316	        // Is it needed to trigger zr event manually if
317	        // the browser do not support `pointer-events: none`.
318	
319	        const self = this;
320	        el.onmouseenter = function () {
321	            // clear the timeout in hideLater and keep showing tooltip
322	            if (self._enterable) {
323	                clearTimeout(self._hideTimeout);
324	                self._show = true;
325	            }
326	            self._inContent = true;
327	        };
328	        el.onmousemove = function (e) {
329	            e = e || (window as any).event;
330	            if (!self._enterable) {
331	                // `pointer-events: none` is set to tooltip content div
332	                // if `enterable` is set as `false`, and `el.onmousemove`
