335	                // Try trigger zrender event to avoid mouse
336	                // in and out shape too frequently
337	                const handler = zr.handler;
338	                const zrViewportRoot = zr.painter.getViewportRoot();
339	                normalizeEvent(zrViewportRoot, e as ZRRawEvent, true);
