385	    show(tooltipModel: Model<TooltipOption>, nearPointColor: ZRColor) {
386	        clearTimeout(this._hideTimeout);
387	        clearTimeout(this._longHideTimeout);
388	        const el = this.el;
389	        const style = el.style;
390	        const styleCoord = this._styleCoord;
391	        if (!el.innerHTML) {
392	            style.display = 'none';
393	        }
394	        else {
395	            style.cssText = gCssText
396	                + assembleCssText(tooltipModel, !this._firstShow, this._longHide)
397	                // initial transform
398	                + assembleTransform(styleCoord[0], styleCoord[1], true)
399	                + `border-color:${convertToColorString(nearPointColor)};`
400	                + (tooltipModel.get('extraCssText') || '')
401	                // If mouse occasionally move over the tooltip, a mouseout event will be
402	                // triggered by canvas, and cause some unexpectable result like dragging
403	                // stop, "unfocusAdjacency". Here `pointer-events: none` is used to solve
404	                // it. Although it is not supported by IE8~IE10, fortunately it is a rare
405	                // scenario.
406	                + `;pointer-events:${this._enterable ? 'auto' : 'none'}`;
407	        }
408	
409	        this._show = true;
410	        this._firstShow = false;
411	        this._longHide = false;
412	    }
413	
414	    setContent(
415	        content: string | HTMLElement | HTMLElement[],
416	        markers: unknown,
417	        tooltipModel: Model<TooltipOption>,
418	        borderColor?: ZRColor,
419	        arrowPosition?: TooltipOption['position']
420	    ) {
421	        const el = this.el;
422	
423	        if (content == null) {
424	            el.innerHTML = '';
425	            return;
426	        }
427	
428	        let arrow = '';
429	        if (isString(arrowPosition) && tooltipModel.get('trigger') === 'item'
430	            && !shouldTooltipConfine(tooltipModel)) {
431	            arrow = assembleArrow(tooltipModel, borderColor, arrowPosition);
432	        }
433	        if (isString(content)) {
434	            el.innerHTML = content + arrow;
435	        }
436	        else if (content) {
437	            // Clear previous
438	            el.innerHTML = '';
439	            if (!isArray(content)) {
440	                content = [content];
441	            }
442	            for (let i = 0; i < content.length; i++) {
443	                if (isDom(content[i]) && content[i].parentNode !== el) {
444	                    el.appendChild(content[i]);
445	                }
446	            }
447	            // no arrow if empty
448	            if (arrow && el.childNodes.length) {
449	                // no need to create a new parent element, but it's not supported by IE 10 and older.
450	                // const arrowEl = document.createRange().createContextualFragment(arrow);
451	                const arrowEl = document.createElement('div');
452	                arrowEl.innerHTML = arrow;
453	                el.appendChild(arrowEl);
454	            }
455	        }
456	    }
