458	    setEnterable(enterable: boolean) {
459	        this._enterable = enterable;
460	    }
461	
462	    getSize() {
463	        const el = this.el;
464	        return [el.offsetWidth, el.offsetHeight];
465	    }
466	
467	    moveTo(zrX: number, zrY: number) {
468	        const styleCoord = this._styleCoord;
469	        makeStyleCoord(styleCoord, this._zr, this._container, zrX, zrY);
470	
471	        if (styleCoord[0] != null && styleCoord[1] != null) {
472	            const style = this.el.style;
473	            const transforms = assembleTransform(styleCoord[0], styleCoord[1]) as string[][];
474	            each(transforms, (transform) => {
475	              style[transform[0] as any] = transform[1];
476	            });
477	        }
478	    }
479	
480	    /**
481	     * when `alwaysShowContent` is true,
482	     * move the tooltip after chart resized
483	     */
484	    _moveIfResized() {
485	        // The ratio of left to width
486	        const ratioX = this._styleCoord[2];
487	        // The ratio of top to height
488	        const ratioY = this._styleCoord[3];
489	        this.moveTo(
490	            ratioX * this._zr.getWidth(),
491	            ratioY * this._zr.getHeight()
492	        );
493	    }
494	
495	    hide() {
496	        const style = this.el.style;
497	        style.visibility = 'hidden';
498	        style.opacity = '0';
499	        env.transform3dSupported && (style.willChange = '');
500	        this._show = false;
501	        this._longHideTimeout = setTimeout(() => this._longHide = true, 500) as any;
502	    }
503	
504	    hideLater(time?: number) {
505	        if (this._show && !(this._inContent && this._enterable) && !this._alwaysShowContent) {
506	            if (time) {
507	                this._hideDelay = time;
508	                // Set show false to avoid invoke hideLater multiple times
509	                this._show = false;
510	                this._hideTimeout = setTimeout(bind(this.hide, this), time) as any;
511	            }
512	            else {
513	                this.hide();
514	            }
515	        }
516	    }
517	
518	    isShow() {
519	        return this._show;
520	    }
521	
522	    dispose() {
523	        clearTimeout(this._hideTimeout);
524	        clearTimeout(this._longHideTimeout);
525	
526	        const parentNode = this.el.parentNode;
527	        parentNode && parentNode.removeChild(this.el);
528	        this.el = this._container = null;
529	    }
530	
531	}
532	
533	export default TooltipHTMLContent;

