/*
* Safeguarding test for: fix(tooltip): fix potential NPE when setting option
* with `notMerge` strategy (upstream apache/echarts#20435).
*
* After a tooltip view is disposed (e.g. when `setOption` is called with
* `notMerge`), `TooltipHTMLContent.el` becomes null. Delayed repositioning or
* size reads (resize with `alwaysShowContent`, pending hide/show timers) must
* not throw on the null element.
*/

import { createChart, removeChart } from '../test/ut/core/utHelper';
import TooltipHTMLContent from '../src/component/tooltip/TooltipHTMLContent';

describe('tooltip notMerge NPE', function () {

    let chart: ReturnType<typeof createChart>;

    afterEach(function () {
        if (chart) {
            removeChart(chart);
            chart = null;
        }
    });

    it('getSize/moveTo tolerate a disposed tooltip content element', function () {
        chart = createChart();
        const zr = chart.getZr();
        const api = {
            getZr: () => zr,
            getDom: () => chart.getDom(),
            getWidth: () => chart.getWidth(),
            getHeight: () => chart.getHeight()
        };
        const content = new TooltipHTMLContent(api as any, {} as any);

        // Before dispose: normal behavior.
        expect(content.getSize()).toEqual([0, 0]);
        expect(function () {
            content.moveTo(10, 10);
        }).not.toThrow();

        // After dispose: must not throw on null el, getSize falls back to [0, 0].
        content.dispose();
        expect(content.getSize()).toEqual([0, 0]);
        expect(function () {
            content.moveTo(20, 20);
        }).not.toThrow();
    });

    it('setOption with notMerge does not crash tooltip logic', function () {
        chart = createChart();
        chart.setOption({
            tooltip: { show: true, alwaysShowContent: true },
            xAxis: { type: 'category', data: ['Mon', 'Tue'] },
            yAxis: {},
            series: [{ type: 'line', data: [1, 2] }]
        });

        chart.dispatchAction({
            type: 'showTip',
            seriesIndex: 0,
            dataIndex: 0
        });

        expect(function () {
            chart.setOption({
                tooltip: { show: true, alwaysShowContent: true },
                xAxis: { type: 'category', data: ['Wed', 'Thu'] },
                yAxis: {},
                series: [{ type: 'line', data: [3, 4] }]
            }, { notMerge: true });
            chart.resize();
        }).not.toThrow();

        // Tooltip still works after rerender.
        expect(function () {
            chart.dispatchAction({
                type: 'showTip',
                seriesIndex: 0,
                dataIndex: 1
            });
            chart.dispatchAction({ type: 'hideTip' });
        }).not.toThrow();
    });
});
